// Exploratory census: fold a prototype stop reason over every committed
// trajectory's session log and cross it with the reward outcome.
import { readdirSync, readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'

const REPO = process.argv[2] as string
const { scanLog } = await import(join(REPO, 'packages/session/session-persistence-jsonl/src/format.ts'))
const RUNS = join(REPO, 'data/proving-ground')

function stopOf(events: any[]): string {
  let stop: string | undefined
  let breach: any
  let open = false
  for (const event of events) {
    switch (event.type) {
      case 'turn/start': open = true; break
      case 'budget/breach':
        breach = event.data
        if ((event.data.scope ?? 'session') === 'session') stop = 'budget'
        break
      case 'turn/end':
        open = false
        stop = event.data.reason.kind === 'blocked' && breach !== undefined ? 'budget' : event.data.reason.kind
        breach = undefined
        break
      case 'environment/delegation':
        stop = event.data.stopReason === 'budget-deadline' ? 'budget' : event.data.stopReason
        breach = undefined
        break
    }
  }
  if (open) return 'interrupted'
  return stop ?? 'none'
}

const table = new Map<string, number>()
let zero = 0
const anyBreach = { zero: 0 }
for (const record of readdirSync(RUNS).sort()) {
  const path = join(RUNS, record, 'trajectories.jsonl')
  if (!existsSync(path)) continue
  for (const line of readFileSync(path, 'utf8').split('\n').filter(Boolean)) {
    const t = JSON.parse(line)
    const log = join(RUNS, record, 'sessions', `${t.id}.jsonl`)
    let stop = 'no-log'
    let breached = false
    if (existsSync(log)) {
      const { events } = scanLog(readFileSync(log))
      stop = stopOf(events)
      breached = events.some((e: any) => e.type === 'budget/breach')
    }
    const key = `${String(t.reward.outcome)}/${t.reward.basis}/${stop}`
    table.set(key, (table.get(key) ?? 0) + 1)
    if (t.reward.outcome === 0) { zero += 1; if (breached) anyBreach.zero += 1 }
  }
}
console.log({ zero, zeroWithAnyBreach: anyBreach.zero })
for (const [key, count] of [...table].sort()) console.log(key.padEnd(48), count)

