// Exploratory: print the terminal events of sessions with a given outcome that recorded a budget breach.
import { readdirSync, readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'

const REPO = process.argv[2] as string
const WANT = process.argv[3] as string
const LIMIT = Number(process.argv[4] ?? 4)
const { scanLog } = await import(join(REPO, 'packages/session/session-persistence-jsonl/src/format.ts'))
const RUNS = join(REPO, 'data/proving-ground')
const KEEP = ['turn/end', 'budget/breach', 'environment/delegation', 'verification/run', 'verification/certificate', 'goal/change']

function brief(e: any): string {
  switch (e.type) {
    case 'turn/end': return JSON.stringify(e.data.reason)
    case 'budget/breach': return JSON.stringify(e.data)
    case 'environment/delegation': return JSON.stringify({ attempt: e.data.attempt, stopReason: e.data.stopReason })
    case 'goal/change': return JSON.stringify({ op: e.data.operation })
    case 'verification/run': return JSON.stringify({ verdict: e.data.verdict })
    default: return ''
  }
}

let shown = 0
for (const record of readdirSync(RUNS).sort()) {
  const path = join(RUNS, record, 'trajectories.jsonl')
  if (!existsSync(path)) continue
  for (const line of readFileSync(path, 'utf8').split('\n').filter(Boolean)) {
    const t = JSON.parse(line)
    if (String(t.reward.outcome) !== WANT) continue
    const log = join(RUNS, record, 'sessions', `${t.id}.jsonl`)
    if (!existsSync(log)) continue
    const { events } = scanLog(readFileSync(log))
    if (!events.some((e: any) => e.type === 'budget/breach')) continue
    console.log(record, t.id, t.environment?.implementer ?? 'route')
    for (const e of events.filter((e: any) => KEEP.includes(e.type)).slice(-8)) console.log('   ', e.seq, e.type, brief(e).slice(0, 160))
    shown += 1
    if (shown >= LIMIT) process.exit(0)
  }
}

