// Prototype of the new shipped rules, run against runtime-assembled fake credential shapes.
const PEM_LABEL = String.raw`(?:[A-Z0-9]+ )*PRIVATE KEY(?: BLOCK)?`
const PEM_GAP = String.raw`(?:\s|\\[nrt])`
const rules = [
  {
    id: 'private-key',
    pattern: String.raw`(?<=-----BEGIN ${PEM_LABEL}-----${PEM_GAP}*)(?:(?!${PEM_GAP}|-----END )\S[\s\S]*?(?=${PEM_GAP}*-----END ${PEM_LABEL}-----)|[A-Za-z0-9+/=:,-]+(?:${PEM_GAP}+[A-Za-z0-9+/=:,-]+)*)`,
    flags: 'g',
    replacement: '[redacted:private-key]',
  },
  { id: 'jwt', pattern: String.raw`\beyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*`, flags: 'g', replacement: '[redacted:jwt]' },
  { id: 'aws-access-key', pattern: String.raw`\b(?:AKIA|ASIA)[0-9A-Z]{16}\b`, flags: 'g', replacement: '[redacted:aws-access-key]' },
  {
    id: 'aws-secret-key',
    pattern: String.raw`(?<=\b(?:aws_?)?secret_?access_?key["']?\s*[:=]\s*["']?)[A-Za-z0-9/+]{40}(?![A-Za-z0-9/+])`,
    flags: 'gi',
    replacement: '[redacted:aws-secret-key]',
  },
  { id: 'github-token', pattern: String.raw`\b(?:gh[oprsu]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{20,})`, flags: 'g', replacement: '[redacted:github-token]' },
  { id: 'slack-token', pattern: String.raw`\bxox[abprs]-[A-Za-z0-9-]{10,}`, flags: 'g', replacement: '[redacted:slack-token]' },
].map(r => ({ ...r, regex: new RegExp(r.pattern, r.flags) }))

const begin = kind => ['-----BEGIN', `${kind}PRIVATE KEY-----`].join(' ')
const end = kind => ['-----END', `${kind}PRIVATE KEY-----`].join(' ')
const body = ['MIIEowIBAAKCAQEA' + 'q'.repeat(48), 'Z'.repeat(64), 'AbC+/9=='].join('\n')
const seg = v => Buffer.from(JSON.stringify(v)).toString('base64url')

const cases = [
  `${begin('RSA ')}\n${body}\n${end('RSA ')}\n`,
  `cat key.pem:\n${begin('')}\n${body}\n${end('')}\ndone`,
  `{"key":"${begin('EC ')}\\n${body.replaceAll('\n', '\\n')}\\n${end('EC ')}\\n"}`,
  `${begin('OPENSSH ')}\n${body}\n[output truncated]`,
  `${begin('RSA ')}\nProc-Type: 4,ENCRYPTED\nDEK-Info: AES-128-CBC,0A1B2C\n\n${body}\n${end('RSA ')}`,
  `two: ${begin('')}\n${body}\n${end('')}\n${begin('EC ')}\n${body}\n${end('EC ')}`,
  `const header = '${begin('')}' // a parser constant with no key after it`,
  `Authorization: Bearer ${seg({ alg: 'HS256', typ: 'JWT' })}.${seg({ sub: 'fixture' })}.${'s'.repeat(43)}`,
  `unsigned ${seg({ alg: 'none' })}.${seg({ a: 1 })}. end`,
  `aws_access_key_id = ${['AKIA', 'FIXTURE0NOTAKEY0'].join('')}`,
  `aws_secret_access_key = ${'w'.repeat(20)}/${'K'.repeat(19)}`,
  `export AWS_SECRET_ACCESS_KEY="${'w'.repeat(40)}"`,
  `"SecretAccessKey": "${'w'.repeat(40)}",`,
  `token ${['ghp', 'x'.repeat(36)].join('_')} and ${['github', 'pat', 'A'.repeat(22), 'b'.repeat(59)].join('_')}`,
  `slack ${['xoxb', '123456789012', '1234567890123', 'x'.repeat(24)].join('-')}`,
  `ghp_short and xoxb-1 and eyJhbGci alone`,
]
for (const text of cases) {
  let out = text
  const hits = {}
  for (const rule of rules) out = out.replace(rule.regex, () => { hits[rule.id] = (hits[rule.id] ?? 0) + 1; return rule.replacement })
  console.log('---', JSON.stringify(hits))
  console.log(out)
}

