    pattern: String.raw`(?<=-----BEGIN ${PEM_LABEL}-----${PEM_GAP})(?:(?!-----END |\\[nrt])\S(?:(?!-----BEGIN )[\s\S])*?(?=${PEM_GAP}-----END ${PEM_LABEL}-----)|${PEM_LINE}(?:${PEM_BREAK}${PEM_LINE})*)`,
