walk(join(runDir, '.sessions'))
copyFileSync(join(runDir, 'trajectories.jsonl'), join(recordDir, 'trajectories.jsonl'))
writeFileSync(join(recordDir, 'manifest.json'), `${JSON.stringify({ run: 'synthetic', files: [{ path: 'trajectories.jsonl', bytes: 0, sha256: '' }] }, null, 2)}\n`)
console.log(readdirSync(join(recordDir, 'sessions')))

