// Census with the shipped fold: stop reason by reward outcome over every committed trajectory whose session log the record keeps.
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

const REPO = process.argv[2] as string
const { scanLog } = await import(join(REPO, 'packages/session/session-persistence-jsonl/src/format.ts'))
const { foldTrajectoryStop } = await import(join(REPO, 'packages/improvement/trajectories/src/index.ts'))
const RUNS = join(REPO, 'data/proving-ground')

const table = new Map<string, number>()
let lines = 0
let missingLogs = 0
for (const record of readdirSync(RUNS).sort()) {
  const path = join(RUNS, record, 'trajectories.jsonl')
  if (!existsSync(path)) continue
  for (const line of readFileSync(path, 'utf8').split('\n').filter(Boolean)) {
    lines += 1
    const trajectory = JSON.parse(line)
    const log = join(RUNS, record, 'sessions', `${trajectory.id}.jsonl`)
    if (!existsSync(log)) { missingLogs += 1; continue }
    const stop = foldTrajectoryStop(scanLog(readFileSync(log)).events)
    const key = `outcome=${String(trajectory.reward.outcome)} stop=${stop}`
    table.set(key, (table.get(key) ?? 0) + 1)
  }
}
console.log({ lines, missingLogs })
for (const [key, count] of [...table].sort()) console.log(key.padEnd(40), count)

