  if (args.some(arg => arg === '--threads' || arg.startsWith('--threads='))) {
    throw new Error('run-oxlint: use DSH_OXLINT_THREADS instead of passing --threads directly.')
  }
  return {
    args: [...args, `--threads=${raw}`],
    env: { ...env, GOMAXPROCS: raw },
  }
}

